tion', 'finished')" col="1">\n                            <p class="oe_grey">\n                                Selected contacts will be merged together.\n                                All documents linked to one of these contacts\n                                will be redirected to the destination contact.\n                                You can remove contacts from this list to avoid merging them.\n                            </p>\n                            <group col="2">\n                                <field name="dst_partner_id" domain="[('id', 'in', partner_ids or False)]" required="state == 'selection'" context="{'partner_show_db_id': True}"/>\n                            </group>\n                            <field name="partner_ids" nolabel="1">\n                                <tree string="Partners">\n                                    <field name="id"/>\n                                    <field name="display_name"/>\n                                    <field name="email"/>\n                                    <field name="is_company"/>\n                                    <field name="vat"/>\n                                    <field name="country_id"/>\n                                </tree>\n                            </field>\n                        </group>\n                    </sheet>\n                    <footer>\n                        <button name="action_merge" string="Merge Contacts" class="oe_highlight" type="object" data-hotkey="q" invisible="state in ('option', 'finished')"/>\n                        <button name="action_skip" string="Skip these contacts" type="object" invisible="state != 'selection'"/>\n                        <button name="action_start_manual_process" string="Merge with Manual Check" data-hotkey="w" type="object" class="oe_highlight" invisible="state != 'option'"/>\n                        <button name="action_start_automatic_process" string="Merge Automatically" data-hotkey="l" type="object" class="oe_h